<?php
/** @var array<string, mixed> $attributes */
declare( strict_types=1 ); if ( ! defined( 'ABSPATH' ) ) { exit; }
$nextsaas_items = nextsaas_items( $attributes, 'items' ); $nextsaas_media = nextsaas_items( $attributes, 'media' );
?>
<section <?php echo nextsaas_section_attrs( 'home-capabilities', $attributes, array( 'section' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?>><div class="container"><div class="section-heading"><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><div class="heading-row"><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><p class="lead" data-nextsaas-rich="lead"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'lead' ) ); ?></p></div></div>
<div class="capability-grid"><?php foreach ( array_slice( $nextsaas_items, 0, 2 ) as $nextsaas_i => $nextsaas_item ) : ?><article class="capability"><?php echo nextsaas_media( $nextsaas_media[ $nextsaas_i ] ?? array(), 'ph-img image-reserve' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?><span class="num" data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_i ); ?>.meta"><?php echo nextsaas_rich( (string) ( $nextsaas_item['meta'] ?? '' ) ); ?></span><h3 data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_i ); ?>.heading"><?php echo nextsaas_rich( (string) ( $nextsaas_item['heading'] ?? '' ) ); ?></h3><p data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_i ); ?>.body"><?php echo nextsaas_rich( (string) ( $nextsaas_item['body'] ?? '' ) ); ?></p></article><?php endforeach; ?></div>
<div class="capability-bottom"><?php foreach ( array_slice( $nextsaas_items, 2 ) as $nextsaas_i => $nextsaas_item ) : $nextsaas_n = $nextsaas_i + 2; ?><article><h3 data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_n ); ?>.heading"><?php echo nextsaas_rich( (string) ( $nextsaas_item['heading'] ?? '' ) ); ?></h3><p data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_n ); ?>.body"><?php echo nextsaas_rich( (string) ( $nextsaas_item['body'] ?? '' ) ); ?></p></article><?php endforeach; ?></div></div></section>
